-- Durable staging, resumable import accounting, and export audit metadata.
-- Workbook contents are stored only in protected staging rows and are purged
-- after the retention window; export audits intentionally contain no cell data.

create table public.import_export_jobs (
  id uuid primary key default gen_random_uuid(),
  direction text not null check (direction in ('import','export')),
  data_type text not null,
  actor_id uuid not null references public.users(id) on delete restrict,
  confirmed_by uuid references public.users(id) on delete restrict,
  template_version integer,
  status text not null check (status in ('preflight','ready','processing','completed','completed_with_errors','failed')),
  total_rows integer not null default 0 check (total_rows >= 0),
  valid_rows integer not null default 0 check (valid_rows >= 0),
  successful_rows integer not null default 0 check (successful_rows >= 0),
  failed_rows integer not null default 0 check (failed_rows >= 0),
  filters jsonb not null default '{}'::jsonb,
  selected_fields jsonb not null default '[]'::jsonb,
  source_name text,
  started_at timestamptz not null default now(),
  confirmed_at timestamptz,
  completed_at timestamptz,
  expires_at timestamptz not null default now() + interval '30 days',
  outcome jsonb not null default '{}'::jsonb
);

create table public.import_export_job_rows (
  job_id uuid not null references public.import_export_jobs(id) on delete cascade,
  row_number integer not null check (row_number > 1),
  source_reference text,
  row_data jsonb not null default '{}'::jsonb,
  issues jsonb not null default '[]'::jsonb,
  status text not null default 'ready' check (status in ('ready','succeeded','failed')),
  result_employee_number bigint,
  error_code text,
  completed_at timestamptz,
  primary key (job_id, row_number)
);

create index import_export_jobs_actor_idx on public.import_export_jobs(actor_id, started_at desc);
create index import_export_job_rows_status_idx on public.import_export_job_rows(job_id, status, row_number);

create table public.import_export_audit (
  id bigint generated by default as identity primary key,
  job_id uuid references public.import_export_jobs(id) on delete set null,
  actor_id uuid not null references public.users(id) on delete restrict,
  direction text not null check (direction in ('import','export')),
  data_type text not null,
  template_version integer,
  fields jsonb not null default '[]'::jsonb,
  filters jsonb not null default '{}'::jsonb,
  row_count integer not null default 0 check (row_count >= 0),
  outcome text not null,
  created_at timestamptz not null default now()
);

alter table public.import_export_jobs enable row level security;
alter table public.import_export_job_rows enable row level security;
alter table public.import_export_audit enable row level security;
revoke all on public.import_export_jobs, public.import_export_job_rows, public.import_export_audit from public, anon, authenticated;
grant select, insert, update, delete on public.import_export_jobs, public.import_export_job_rows to service_role;
grant select, insert on public.import_export_audit to service_role;
grant usage, select on sequence public.import_export_audit_id_seq to service_role;

insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('import-export','HMS Import Export',false,20971520,array['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
on conflict (id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

