-- A bounded batch is processed with one transaction per row. A successful
-- target write and its succeeded marker commit together, making retries safe.
create or replace function public.import_export_process_batch(p_job_id uuid, p_limit integer default 25)
returns jsonb language plpgsql security definer set search_path = pg_catalog, public, pg_temp as $$
declare
  v_job public.import_export_jobs%rowtype;
  v_row record;
  v_data jsonb;
  v_employee_id uuid;
  v_employee_number bigint;
  v_wife_id bigint;
  v_table text;
  v_master_id bigint;
  v_count integer;
  v_ok integer := 0;
  v_failed integer := 0;
  v_total integer;
  v_valid integer;
begin
  select * into v_job from public.import_export_jobs where id = p_job_id for update;
  if not found or v_job.direction <> 'import' or v_job.confirmed_at is null then raise exception 'HMS_IMPORT_JOB_NOT_CONFIRMED'; end if;
  if v_job.status not in ('processing','ready','completed_with_errors') then raise exception 'HMS_IMPORT_JOB_NOT_RESUMABLE'; end if;
  update public.import_export_jobs set status='processing' where id=p_job_id;
  for v_row in select * from public.import_export_job_rows where job_id=p_job_id and status='ready' and issues='[]'::jsonb order by row_number limit least(greatest(coalesce(p_limit,25),1),50) for update skip locked loop
    v_data := v_row.row_data;
    begin
      v_employee_id := null;
      v_employee_number := null;
      if v_job.data_type = 'employees' then
        if nullif(v_data->>'employee_number','') is not null then
          select id, employee_number into v_employee_id, v_employee_number from public.employees where employee_number=(v_data->>'employee_number')::bigint for update;
          if not found then raise exception 'HMS_EMPLOYEE_NUMBER_NOT_FOUND'; end if;
          update public.employees set
            employee_status=case when v_data->>'employee_status'='resigned' then employee_status else coalesce(v_data->>'employee_status',employee_status) end, gender=coalesce(v_data->>'gender',gender), arabic_full_name=coalesce(v_data->>'arabic_full_name',arabic_full_name), english_full_name=coalesce(v_data->>'english_full_name',english_full_name), identity_card_number=coalesce(v_data->>'identity_card_number',identity_card_number), identity_card_expiration_date=coalesce((v_data->>'identity_card_expiration_date')::date,identity_card_expiration_date), date_of_birth=coalesce((v_data->>'date_of_birth')::date,date_of_birth), religion_id=coalesce((v_data->>'religion_id')::bigint,religion_id), marital_status_id=coalesce((v_data->>'marital_status_id')::bigint,marital_status_id), diploma_id=coalesce((v_data->>'diploma_id')::bigint,diploma_id), major=coalesce(v_data->>'major',major), graduated_from=coalesce(v_data->>'graduated_from',graduated_from), phone=coalesce(v_data->>'phone',phone), governorate_id=coalesce((v_data->>'governorate_id')::bigint,governorate_id), address=coalesce(v_data->>'address',address), department_id=coalesce((v_data->>'department_id')::bigint,department_id), shift_type_id=coalesce((v_data->>'shift_type_id')::bigint,shift_type_id), team_id=coalesce((v_data->>'team_id')::bigint,team_id), position_id=coalesce((v_data->>'position_id')::bigint,position_id), project_id=coalesce((v_data->>'project_id')::bigint,project_id), joining_date=coalesce((v_data->>'joining_date')::date,joining_date), contract_signing_date=coalesce((v_data->>'contract_signing_date')::date,contract_signing_date), social_insurance_active=coalesce((v_data->>'social_insurance_active')::boolean,social_insurance_active), social_insurance_comment=coalesce(v_data->>'social_insurance_comment',social_insurance_comment), form_1_incoming_number=coalesce(v_data->>'form_1_incoming_number',form_1_incoming_number), form_1_incoming_date=coalesce((v_data->>'form_1_incoming_date')::date,form_1_incoming_date), bank_id=coalesce((v_data->>'bank_id')::bigint,bank_id), bank_account_holder_name=coalesce(v_data->>'bank_account_holder_name',bank_account_holder_name), bank_account_number=coalesce(v_data->>'bank_account_number',bank_account_number), iban=coalesce(v_data->>'iban',iban), bank_branch=coalesce(v_data->>'bank_branch',bank_branch), leaving_date=coalesce((v_data->>'leaving_date')::date,leaving_date), leaving_reason_id=coalesce((v_data->>'leaving_reason_id')::bigint,leaving_reason_id), leaving_comment=coalesce(v_data->>'leaving_comment',leaving_comment), annual_days_settled=coalesce((v_data->>'annual_days_settled')::numeric,annual_days_settled), form_6_incoming_number=coalesce(v_data->>'form_6_incoming_number',form_6_incoming_number), form_6_incoming_date=coalesce((v_data->>'form_6_incoming_date')::date,form_6_incoming_date), form_6_reason=coalesce(v_data->>'form_6_reason',form_6_reason), updated_by=v_job.actor_id
          where id=v_employee_id and updated_at=(v_data->>'expected_updated_at')::timestamptz returning employee_number into v_employee_number;
          if not found then raise exception 'HMS_EMPLOYEE_CHANGED_REVIEW'; end if;
        else
          insert into public.employees (employee_status,employee_classification,gender,arabic_full_name,english_full_name,identity_card_number,identity_card_expiration_date,date_of_birth,religion_id,marital_status_id,diploma_id,major,graduated_from,phone,governorate_id,address,department_id,shift_type_id,team_id,position_id,project_id,joining_date,contract_signing_date,social_insurance_active,social_insurance_comment,form_1_incoming_number,form_1_incoming_date,bank_id,bank_account_holder_name,bank_account_number,iban,bank_branch,created_by,updated_by)
          values ('active',coalesce(v_data->>'employee_classification','standard'),v_data->>'gender',v_data->>'arabic_full_name',v_data->>'english_full_name',v_data->>'identity_card_number',(v_data->>'identity_card_expiration_date')::date,(v_data->>'date_of_birth')::date,(v_data->>'religion_id')::bigint,(v_data->>'marital_status_id')::bigint,(v_data->>'diploma_id')::bigint,v_data->>'major',v_data->>'graduated_from',v_data->>'phone',(v_data->>'governorate_id')::bigint,v_data->>'address',(v_data->>'department_id')::bigint,(v_data->>'shift_type_id')::bigint,(v_data->>'team_id')::bigint,(v_data->>'position_id')::bigint,(v_data->>'project_id')::bigint,(v_data->>'joining_date')::date,(v_data->>'contract_signing_date')::date,coalesce((v_data->>'social_insurance_active')::boolean,false),v_data->>'social_insurance_comment',v_data->>'form_1_incoming_number',(v_data->>'form_1_incoming_date')::date,(v_data->>'bank_id')::bigint,v_data->>'bank_account_holder_name',v_data->>'bank_account_number',v_data->>'iban',v_data->>'bank_branch',v_job.actor_id,v_job.actor_id)
          returning id,employee_number into v_employee_id,v_employee_number;
        end if;
        if v_data ? 'employee_status' and v_data->>'employee_status'='resigned' then
          if not exists(select 1 from public.employees where id=v_employee_id and employee_status in ('active','resigned') and leaving_date is not null and leaving_reason_id is not null) then raise exception 'HMS_LIFECYCLE_IMPORT_INVALID'; end if;
          update public.employees set employee_status='resigned',leaving_date=coalesce((v_data->>'leaving_date')::date,leaving_date),leaving_reason_id=coalesce((v_data->>'leaving_reason_id')::bigint,leaving_reason_id),leaving_comment=coalesce(v_data->>'leaving_comment',leaving_comment),annual_days_settled=coalesce((v_data->>'annual_days_settled')::numeric,annual_days_settled),form_6_incoming_number=coalesce(v_data->>'form_6_incoming_number',form_6_incoming_number),form_6_incoming_date=coalesce((v_data->>'form_6_incoming_date')::date,form_6_incoming_date),form_6_reason=coalesce(v_data->>'form_6_reason',form_6_reason),updated_by=v_job.actor_id where id=v_employee_id returning employee_number into v_employee_number;
        elsif v_data ? 'employee_status' and v_data->>'employee_status'='active' and exists(select 1 from public.employees where id=v_employee_id and employee_status='resigned') then raise exception 'HMS_RESIGNED_EMPLOYEE_REACTIVATION_BLOCKED'; end if;
        perform public.refresh_employee_notifications(v_employee_id);
      elsif v_job.data_type in ('spouses','children','licenses','social_insurance','documents') then
        select id,employee_number into v_employee_id,v_employee_number from public.employees where employee_number=(v_data->>'employee_number')::bigint;
        if not found then raise exception 'HMS_EMPLOYEE_NUMBER_NOT_FOUND'; end if;
        if v_job.data_type='spouses' then
          insert into public.employee_wives(employee_id,wife_name,identity_card_number,is_working,created_by,updated_by) values(v_employee_id,v_data->>'wife_name',v_data->>'identity_card_number',coalesce((v_data->>'is_working')::boolean,false),v_job.actor_id,v_job.actor_id) on conflict(employee_id,identity_card_number) do update set wife_name=excluded.wife_name,is_working=excluded.is_working,updated_by=v_job.actor_id,updated_at=now();
        elsif v_job.data_type='children' then
          v_wife_id:=null;
          if nullif(v_data->>'wife_name','') is not null then select count(*),min(id) into v_count,v_wife_id from public.employee_wives where employee_id=v_employee_id and lower(btrim(wife_name))=lower(btrim(v_data->>'wife_name')); if v_count=0 then raise exception 'HMS_CHILD_SPOUSE_NOT_FOUND'; elsif v_count>1 then raise exception 'HMS_CHILD_SPOUSE_AMBIGUOUS'; end if; end if;
          insert into public.employee_children(employee_id,wife_id,child_name,identity_card_number,created_by,updated_by) values(v_employee_id,v_wife_id,v_data->>'child_name',v_data->>'identity_card_number',v_job.actor_id,v_job.actor_id) on conflict(employee_id,identity_card_number) do update set child_name=excluded.child_name,wife_id=excluded.wife_id,updated_by=v_job.actor_id,updated_at=now();
        elsif v_job.data_type='licenses' then
          select count(*) into v_count from public.employee_licenses where employee_id=v_employee_id and license_type_id=(v_data->>'license_type_id')::bigint and release_date=(v_data->>'release_date')::date and expiry_date=(v_data->>'expiry_date')::date;
          if v_count>1 then raise exception 'HMS_LICENSE_MATCH_AMBIGUOUS'; end if;
          if v_count=0 then insert into public.employee_licenses(employee_id,license_type_id,release_date,expiry_date,created_by,updated_by) values(v_employee_id,(v_data->>'license_type_id')::bigint,(v_data->>'release_date')::date,(v_data->>'expiry_date')::date,v_job.actor_id,v_job.actor_id); end if;
        elsif v_job.data_type='social_insurance' then
          insert into public.employee_social_insurance(employee_id,form_1_installation_date,form_1_social_insurance_number,form_1_incoming_number,form_1_incoming_date,form_1_insurance_status_text,form_1_notes,form_6_termination_date,form_6_termination_reason,form_6_social_insurance_number,form_6_incoming_number,form_6_incoming_date,form_6_insurance_status_text,form_6_notes,updated_by)
          values(v_employee_id,(v_data->>'form_1_installation_date')::date,v_data->>'form_1_social_insurance_number',v_data->>'form_1_incoming_number',(v_data->>'form_1_incoming_date')::date,v_data->>'form_1_insurance_status_text',v_data->>'form_1_notes',(v_data->>'form_6_termination_date')::date,v_data->>'form_6_termination_reason',v_data->>'form_6_social_insurance_number',v_data->>'form_6_incoming_number',(v_data->>'form_6_incoming_date')::date,v_data->>'form_6_insurance_status_text',v_data->>'form_6_notes',v_job.actor_id)
          on conflict(employee_id) do update set form_1_installation_date=coalesce(excluded.form_1_installation_date,employee_social_insurance.form_1_installation_date),form_1_social_insurance_number=coalesce(excluded.form_1_social_insurance_number,employee_social_insurance.form_1_social_insurance_number),form_1_incoming_number=coalesce(excluded.form_1_incoming_number,employee_social_insurance.form_1_incoming_number),form_1_incoming_date=coalesce(excluded.form_1_incoming_date,employee_social_insurance.form_1_incoming_date),form_1_insurance_status_text=coalesce(excluded.form_1_insurance_status_text,employee_social_insurance.form_1_insurance_status_text),form_1_notes=coalesce(excluded.form_1_notes,employee_social_insurance.form_1_notes),form_6_termination_date=coalesce(excluded.form_6_termination_date,employee_social_insurance.form_6_termination_date),form_6_termination_reason=coalesce(excluded.form_6_termination_reason,employee_social_insurance.form_6_termination_reason),form_6_social_insurance_number=coalesce(excluded.form_6_social_insurance_number,employee_social_insurance.form_6_social_insurance_number),form_6_incoming_number=coalesce(excluded.form_6_incoming_number,employee_social_insurance.form_6_incoming_number),form_6_incoming_date=coalesce(excluded.form_6_incoming_date,employee_social_insurance.form_6_incoming_date),form_6_insurance_status_text=coalesce(excluded.form_6_insurance_status_text,employee_social_insurance.form_6_insurance_status_text),form_6_notes=coalesce(excluded.form_6_notes,employee_social_insurance.form_6_notes),updated_by=v_job.actor_id,version=employee_social_insurance.version+1,updated_at=now();
        elsif v_job.data_type='documents' then
          raise exception 'HMS_DOCUMENT_IMPORT_REQUIRES_ATTACHMENT_WORKFLOW';
        end if;
      elsif v_job.data_type='hiring_plans' then
        insert into public.project_hiring_plans(project_id,department_id,position_id,planned_count,created_by,updated_by) values((v_data->>'project_id')::bigint,(v_data->>'department_id')::bigint,(v_data->>'position_id')::bigint,(v_data->>'planned_count')::integer,v_job.actor_id,v_job.actor_id)
        on conflict(project_id,department_id,position_id) do update set planned_count=excluded.planned_count,updated_by=v_job.actor_id,updated_at=now();
      elsif v_job.data_type like 'setup_%' then
        v_table:=substring(v_job.data_type from 7);
        if v_table not in ('departments','teams','positions','projects','banks','license_types','religions','marital_statuses','diplomas','governorates','shift_types','leaving_reasons') then raise exception 'HMS_SETUP_IMPORT_TYPE_UNSUPPORTED'; end if;
        execute format('select count(*),min(id) from public.%I where lower(btrim(name))=lower(btrim($1))',v_table) into v_count,v_master_id using v_data->>'name';
        if v_count>1 then raise exception 'HMS_SETUP_NAME_AMBIGUOUS'; end if;
        if v_table='positions' and nullif(v_data->>'position_code','') is null then raise exception 'HMS_POSITION_CODE_REQUIRED'; end if;
        if v_count=1 then
          if v_table='positions' then execute 'update public.positions set description=coalesce($1,description),position_code=coalesce($2,position_code),is_active=coalesce($3,is_active),updated_by=$4,updated_at=now() where id=$5' using v_data->>'description',v_data->>'position_code',(v_data->>'is_active')::boolean,v_job.actor_id,v_master_id;
          elsif v_table='governorates' then execute 'update public.governorates set description=coalesce($1,description),is_active=coalesce($2,is_active),participates_in_comprehensive_health_insurance=coalesce($3,participates_in_comprehensive_health_insurance),updated_by=$4,updated_at=now() where id=$5' using v_data->>'description',(v_data->>'is_active')::boolean,(v_data->>'participates_in_comprehensive_health_insurance')::boolean,v_job.actor_id,v_master_id;
          else execute format('update public.%I set description=coalesce($1,description),is_active=coalesce($2,is_active),updated_by=$3,updated_at=now() where id=$4',v_table) using v_data->>'description',(v_data->>'is_active')::boolean,v_job.actor_id,v_master_id; end if;
        else
          if v_table='positions' then execute 'insert into public.positions(name,position_code,description,is_active,created_by,updated_by) values($1,$2,$3,coalesce($4,true),$5,$5)' using v_data->>'name',v_data->>'position_code',v_data->>'description',(v_data->>'is_active')::boolean,v_job.actor_id;
          elsif v_table='governorates' then execute 'insert into public.governorates(name,description,is_active,participates_in_comprehensive_health_insurance,created_by,updated_by) values($1,$2,coalesce($3,true),coalesce($4,false),$5,$5)' using v_data->>'name',v_data->>'description',(v_data->>'is_active')::boolean,(v_data->>'participates_in_comprehensive_health_insurance')::boolean,v_job.actor_id;
          else execute format('insert into public.%I(name,description,is_active,created_by,updated_by) values($1,$2,coalesce($3,true),$4,$4)',v_table) using v_data->>'name',v_data->>'description',(v_data->>'is_active')::boolean,v_job.actor_id; end if;
        end if;
      else
        raise exception 'HMS_IMPORT_TYPE_UNSUPPORTED';
      end if;
      update public.import_export_job_rows set status='succeeded',result_employee_number=v_employee_number,completed_at=now() where job_id=p_job_id and row_number=v_row.row_number;
      v_ok := v_ok + 1;
    exception when others then
      update public.import_export_job_rows set status='failed',error_code=case when sqlerrm like 'HMS_%' then sqlerrm else 'HMS_ROW_WRITE_FAILED' end,completed_at=now() where job_id=p_job_id and row_number=v_row.row_number;
      v_failed := v_failed + 1;
    end;
  end loop;
  select count(*) into v_total from public.import_export_job_rows where job_id=p_job_id;
  select count(*) into v_valid from public.import_export_job_rows where job_id=p_job_id and issues='[]'::jsonb;
  update public.import_export_jobs j set successful_rows=(select count(*) from public.import_export_job_rows r where r.job_id=p_job_id and r.status='succeeded'),failed_rows=(select count(*) from public.import_export_job_rows r where r.job_id=p_job_id and r.status='failed'),status=case when not exists(select 1 from public.import_export_job_rows r where r.job_id=p_job_id and r.status='ready') then case when exists(select 1 from public.import_export_job_rows r where r.job_id=p_job_id and r.status='failed') or v_valid<v_total then 'completed_with_errors' else 'completed' end else 'processing' end,completed_at=case when not exists(select 1 from public.import_export_job_rows r where r.job_id=p_job_id and r.status='ready') then now() else null end where j.id=p_job_id returning total_rows,valid_rows into v_total,v_valid;
  return jsonb_build_object('job_id',p_job_id,'successful_rows',v_ok,'failed_rows',v_failed,'complete',not exists(select 1 from public.import_export_job_rows where job_id=p_job_id and status='ready'));
end;
$$;

revoke all on function public.import_export_process_batch(uuid,integer) from public, anon, authenticated;
grant execute on function public.import_export_process_batch(uuid,integer) to service_role;
